<template><view class="lf"><view class="ft"><view class="tb" :class="{a:mode==='pwd'}" @tap="mode='pwd'">密码登录</view><view class="tb" :class="{a:mode==='sms'}" @tap="mode='sms'">短信登录</view></view><view v-if="mode==='pwd'" class="fb"><view class="ig"><text class="il">用户名</text><input class="inp" v-model="f.username" placeholder="请输入用户名" placeholder-style="color:#64748B"/></view><view class="ig"><text class="il">密码</text><input class="inp" v-model="f.password" type="password" placeholder="请输入密码" placeholder-style="color:#64748B"/></view><button class="sb" :loading="ld" @tap="doLogin">登录</button></view><view v-if="mode==='sms'" class="fb"><view class="ig"><text class="il">手机号</text><input class="inp" v-model="sf.phone" type="number" maxlength="11" placeholder="请输入手机号" placeholder-style="color:#64748B"/></view><view class="ig ir"><input class="inp f1" v-model="sf.code" type="number" maxlength="6" placeholder="验证码" placeholder-style="color:#64748B"/><button class="smsb" :disabled="scd>0" @tap="sendSms">{{scd>0?scd+'s':'获取验证码'}}</button></view><button class="sb" :loading="ld" @tap="doSmsLogin">登录</button></view><view class="ff"><text class="fl" @tap="$emit('swReg')">还没有账户？立即注册</text></view></view></template>
<script setup>
import {ref,reactive} from 'vue';import {authAPI} from '@/api/auth';import {smsAPI} from '@/api/sms';import {useUserStore} from '@/stores/user';import {isValidPhone} from '@/utils/validate'
const emit=defineEmits(['success','swReg']);const us=useUserStore();const mode=ref('pwd');const ld=ref(false);const scd=ref(0)
const f=reactive({username:'',password:''});const sf=reactive({phone:'',code:''});let t=null
const doLogin=async()=>{if(!f.username.trim()||!f.password){uni.showToast({title:'请填写完整信息',icon:'none'});return};ld.value=true;try{const r=await authAPI.login({username:f.username.trim(),password:f.password});if(r.token){us.login(r,r.token);uni.showToast({title:'登录成功',icon:'success'});setTimeout(()=>uni.switchTab({url:'/pages/home/home'}),500);emit('success',r)}}catch(e){uni.showToast({title:e?.error||'登录失败',icon:'none'})}finally{ld.value=false}}
const sendSms=async()=>{if(!isValidPhone(sf.phone)){uni.showToast({title:'手机号格式不正确',icon:'none'});return};try{await smsAPI.sendSms(sf.phone);uni.showToast({title:'验证码已发送',icon:'success'});scd.value=60;t=setInterval(()=>{scd.value--;if(scd.value<=0)clearInterval(t)},1000)}catch(e){uni.showToast({title:'发送失败',icon:'none'})}}
const doSmsLogin=async()=>{if(!isValidPhone(sf.phone)||!sf.code){uni.showToast({title:'请填写完整信息',icon:'none'});return};ld.value=true;try{const r=await authAPI.loginByPhone(sf.phone,sf.code);if(r.token){us.login(r,r.token);uni.showToast({title:'登录成功',icon:'success'});setTimeout(()=>uni.switchTab({url:'/pages/home/home'}),500);emit('success',r)}}catch(e){uni.showToast({title:e?.error||'登录失败',icon:'none'})}finally{ld.value=false}}
</script>
<style scoped>.lf{padding:28rpx 0}.ft{display:flex;gap:16rpx;margin-bottom:36rpx;background:rgba(255,255,255,.04);border-radius:999rpx;padding:6rpx}.tb{flex:1;height:72rpx;display:flex;align-items:center;justify-content:center;border-radius:999rpx;font-size:28rpx;color:rgba(200,218,242,.65);transition:.2s}.tb.a{background:linear-gradient(135deg,rgba(94,234,212,.18),rgba(56,189,248,.28));color:#f0f6ff;font-weight:700}.fb{display:flex;flex-direction:column;gap:24rpx}.ig{display:flex;flex-direction:column;gap:10rpx}.ir{flex-direction:row}.il{font-size:24rpx;color:rgba(210,225,245,.75);font-weight:600}.inp{height:88rpx;padding:0 24rpx;border-radius:16rpx;border:1px solid rgba(125,211,252,.12);background:rgba(255,255,255,.04);color:#f0f6ff;font-size:28rpx}.f1{flex:1}.smsb{height:88rpx;padding:0 28rpx;border-radius:16rpx;border:1px solid rgba(125,211,252,.16);background:rgba(56,189,248,.1);color:#70d6ff;font-size:24rpx;white-space:nowrap}.sb{height:92rpx;border-radius:20rpx;background:linear-gradient(135deg,#5eead4,#38bdf8);color:#032032;font-size:30rpx;font-weight:700;border:none}.ff{margin-top:36rpx;text-align:center}.fl{color:#70d6ff;font-size:26rpx}</style>
